def _assign_workers_to_aggregation_points(self):
    # Step 1: Ensure INA placement candidates are determined
    self._determine_ina_placement_candidates()

    # Initialize the worker assignment map
    self._worker_assignment_map = {}

    # For each job, assign workers to optimal aggregation points
    for j in range(self.jobs_num):
        self._worker_assignment_map[j] = {}
        job_workers = self.workers_id[j]
        job_ps = self.ps_id[j]

        # Build list of candidate aggregation points: INA switches + PS
        candidate_aggregation_points = self._ina_placement_candidates + [job_ps]

        # For each worker, evaluate all valid assignment options
        worker_assignments = {}

        for w_idx, worker_node in enumerate(job_workers):
            best_score = -float('inf')
            best_assignment = None

            for candidate in candidate_aggregation_points:
                # Check if candidate is a valid INA switch (if not, only consider PS)
                if candidate != job_ps and candidate not in self._ina_placement_candidates:
                    continue

                # Get the path from worker to candidate
                path = self._get_path_links(worker_node, candidate)
                if not path:
                    continue

                # Score: shorter path (fewer hops) is better
                path_length = len(path)

                # Bonus: if candidate is the PS, prefer it only if no INA is available
                # But if INA is available, prioritize INA to reduce PS load
                if candidate == job_ps:
                    # PS is a fallback; penalize it unless no INA is available
                    if self._ina_placement_candidates:
                        score = -path_length - 10  # Penalize PS if INA is available
                    else:
                        score = -path_length  # Only option
                else:
                    # INA switch: prioritize shorter path, but avoid overloading
                    # Use path length as primary score
                    score = -path_length  # Negative for min-heap logic

                # Update best assignment
                if score > best_score:
                    best_score = score
                    best_assignment = candidate

            # Assign the best valid candidate to this worker
            self._worker_assignment_map[j][w_idx] = best_assignment
